import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./SpendingPriority.css";

function SpendingPriority({ updateData }) {
  const navigate = useNavigate();

  const categories = [
    "Food & Groceries",
    "Shopping",
    "Bills",
    "Health",
    "Entertainment",
    "Transport"
  ];

  const [priorities, setPriorities] = useState({});
  const [activeCard, setActiveCard] = useState(null);

  const handleCardClick = (category) => {
    setActiveCard(activeCard === category ? null : category);
  };

  const handleSliderChange = (category, value) => {
    setPriorities(prev => ({
      ...prev,
      [category]: parseInt(value)   // ✅ force number
    }));
  };

  const handleContinue = () => {
    console.log("Saved priorities →", priorities); // ✅ debug
    updateData({ spendingPriorities: priorities });
    navigate("/budget");
  };

  return (
    <div className="income-container">
      <h2 className="income-title">Set Spending Priority</h2>
      <p className="income-subtitle">Click a category to set importance</p>

      <div className="income-grid">
        {categories.map((cat) => (
          <div
            key={cat}
            className="income-card"
            onClick={() => handleCardClick(cat)}
          >
            <div className="income-name">{cat}</div>

            {activeCard === cat && (
              <input
                type="range"
                min="0"
                max="5"
                value={priorities[cat] ?? 0}
                onChange={(e) => handleSliderChange(cat, e.target.value)}
              />
            )}
          </div>
        ))}
      </div>

      <button className="next-button" onClick={handleContinue}>
        Continue
      </button>
    </div>
  );
}

export default SpendingPriority;
